from pathlib import Path
p=Path('outputs')
s=(p/'tomeris_backup_v034.py').read_text(encoding='utf-8').replace("'research_sources.json')","'research_sources.json','research_history.json')")
s=s.replace('MAX_FILE_BYTES=','from tomeris_research_journal import validate as validate_journal, MAX_BYTES as MAX_JOURNAL_BYTES\nMAX_FILE_BYTES=',1)
s=s.replace("limit=MAX_SOURCE_BYTES if name=='research_sources.json' else MAX_FILE_BYTES","limit=MAX_SOURCE_BYTES if name=='research_sources.json' else (MAX_JOURNAL_BYTES if name=='research_history.json' else MAX_FILE_BYTES)")
s=s.replace("if name=='research_sources.json':validate_catalogue(data)","if name=='research_sources.json':validate_catalogue(data)\n            if name=='research_history.json':validate_journal(data)")
s=s.replace("'app_version':'0.34'","'app_version':'0.43'").replace('保存した調査資料と資料学習','調査履歴・保存した調査資料と資料学習')
(p/'tomeris_backup_v043.py').write_text(s,encoding='utf-8')
s=(p/'tomeris_restore_v034.py').read_text(encoding='utf-8').replace('tomeris_backup_v034','tomeris_backup_v043')
s=s.replace('MAX_ARCHIVE_BYTES=', 'from tomeris_research_journal import validate as validate_journal, MAX_BYTES as MAX_JOURNAL_BYTES\n\nMAX_ARCHIVE_BYTES=',1)
s=s.replace("(MAX_FILE_BYTES if entry.filename in FILES else 64*1024)","(MAX_JOURNAL_BYTES if entry.filename=='research_history.json' else (MAX_FILE_BYTES if entry.filename in FILES else 64*1024))")
s=s.replace("MAX_SOURCE_BYTES if name=='research_sources.json' else MAX_FILE_BYTES)","MAX_SOURCE_BYTES if name=='research_sources.json' else (MAX_JOURNAL_BYTES if name=='research_history.json' else MAX_FILE_BYTES))")
s=s.replace("elif name=='daily_plans.json':","elif name=='research_history.json':\n                    validate_journal(document)\n                    counts['research_history']=len(document['records'])\n                elif name=='daily_plans.json':")
(p/'tomeris_restore_v043.py').write_text(s,encoding='utf-8')
s=(p/'tomeris_desktop_v042.py').read_text(encoding='utf-8').replace('v0.42','v0.43').replace('from tomeris_source_followup import','from tomeris_research_history_service import').replace('from tomeris_backup_v034 import','from tomeris_backup_v043 import').replace('from tomeris_restore_v034 import','from tomeris_restore_v043 import')
(p/'tomeris_desktop_v043.py').write_text(s,encoding='utf-8')
